#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct Node {
    long value;
    struct Node *left;
    struct Node *right;
} Node;

static bool printed = false;

static Node *new_node(long v)
{
    Node *n = malloc(sizeof(*n));
    if (!n) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    n->value = v;
    n->left = n->right = NULL;
    return n;
}

static Node *bst_insert(Node *root, long v)
{
    if (root == NULL)
        return new_node(v);
    if (v < root->value)
        root->left = bst_insert(root->left, v);
    else
        root->right = bst_insert(root->right, v);
    return root;
}

static void print_value(long v)
{
    if (printed)
        putchar(' ');
    printf("%ld", v);
    printed = true;
}

static void inorder(Node *root)
{
    if (!root) return;
    inorder(root->left);
    print_value(root->value);
    inorder(root->right);
}

static void preorder(Node *root)
{
    if (!root) return;
    print_value(root->value);
    preorder(root->left);
    preorder(root->right);
}

static void postorder(Node *root)
{
    if (!root) return;
    postorder(root->left);
    postorder(root->right);
    print_value(root->value);
}

static void free_tree(Node *root)
{
    if (!root) return;
    free_tree(root->left);
    free_tree(root->right);
    free(root);
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID_MODE");
        return 0;
    }
    const char *mode = argv[1];
    Node *root = NULL;
    for (int i = 2; i < argc; ++i) {
        char *endptr;
        long v = strtol(argv[i], &endptr, 10);
        (void)endptr; // ignore errors, same as original
        root = bst_insert(root, v);
    }
    if (strcmp(mode, "in") == 0) {
        if (root == NULL) {
            puts("EMPTY");
        } else {
            inorder(root);
            putchar('\n');
        }
    } else if (strcmp(mode, "pre") == 0) {
        if (root == NULL) {
            puts("EMPTY");
        } else {
            preorder(root);
            putchar('\n');
        }
    } else if (strcmp(mode, "post") == 0) {
        if (root == NULL) {
            puts("EMPTY");
        } else {
            postorder(root);
            putchar('\n');
        }
    } else {
        puts("INVALID_MODE");
    }
    free_tree(root);
    return 0;
}
